# -*- coding: utf-8 -*-
# Catechism bank — the ʿalāqa question sheet (research/sources/alaka-suallar.txt, 70 Ottoman sual), items 1–24.
# The answers are the madrasah's own ʿalāqa notes (research/sources/alaka-ilm-bayan.txt): the Arabic is the notes' vowelled
# definitions and their Qurʾānic / proverbial witnesses, the Turkish is the notes' answer in today's spelling, the English is ours.
ITEMS = [
 {"n": 1, "q": {"tr": "Alâka'da neden bahsedilir?", "en": "What does the ʿAlāqa treat?"},
  "a": {"tr": "Beyan bahsinin hakikat, mecaz ve kinâyesinden; mecâz-ı mürselin yirmi yedi alâkasından; istiârenin selef, Sekkâkî ve Hatîb-i Dımaşkî'ye göre kısımlarından; mutlak mecazın dört kısmından ve kinâyenin kısımlarından.", "en": "The bayān's ḥaqīqa, majāz and kināya; the twenty-seven relations of the majāz mursal; the kinds of istiʿāra according to the early masters, al-Sakkākī and the Khaṭīb of Damascus; the four kinds of majāz absolutely; and the kinds of kināya."},
  "ar": ["الْحَقِيقَةُ وَالْمَجَازُ وَالْكِنَايَةُ"], "notes": ["ilm-al-bayan", "majaz-mursal"]},
 {"n": 2, "q": {"tr": "Alâka ne kelimedir?", "en": "What kind of word is «ʿalāqa»?"},
  "a": {"tr": "عَلِقَ fiilinden فَعَالَة vezninde bir isimdir; lügatte bağ, ilişki demektir. Istılahta, lafzın hakikî mânâsı ile mecâzî mânâsı arasında, birinden diğerine intikal olunan ittisaldir — küllî olarak müstamelün fîhin mevzûun lehe lâzım olması.", "en": "A noun on فَعَالَة from عَلِقَ, meaning in the language a tie or attachment. As a term, the connection between a word's literal and figurative meanings by which the mind passes from one to the other — in general, the figurative sense being entailed by the literal."},
  "ar": ["الْعَلَاقَةُ"], "notes": ["majaz-mursal", "qarinat-al-majaz"]},
 {"n": 3, "q": {"tr": "Alâka'nın musannifi kimdir?", "en": "Who is the author of the ʿAlāqa?"},
  "a": {"tr": "Soru kâğıdı cevabı taşımaz; medrese geleneğinde «Alâka» diye okutulan istiâre risâlesi İsâmüddin el-İsferâyînî'ye (ö. 945/1538) nisbet edilir ve bu notlar onun tertibini (selef, Sekkâkî, Hatîb) izler.", "en": "The sheet carries no answer; in the madrasa tradition the istiʿāra treatise read as «ʿAlāqa» is ascribed to ʿIṣām al-Dīn al-Isfarāyīnī (d. 945/1538), whose arrangement — the early masters, al-Sakkākī, the Khaṭīb — these notes follow."},
  "ar": ["رِسَالَةُ الِاسْتِعَارَةِ"], "notes": ["ilm-al-bayan"]},
 {"n": 4, "q": {"tr": "İlm-i beyânın tarifi, mevzuu ve gayesi nedir?", "en": "How is ʿilm al-bayān defined, and what are its subject and its aim?"},
  "a": {"tr": "Tarifi: bir mânâyı, ona delâletin açıklığında farklı yollarla getirmenin kendisiyle bilindiği ilimdir. Mevzuu: teşbih, mecaz ve kinâye. Gayesi: Arapça kelâmın sırlarına vâkıf olup murad olunan mânâyı tayinde hatadan sakınmaktır.", "en": "A science by which is known how to bring one meaning by different ways that differ in the plainness of their indication. Its subject: tashbīh, majāz and kināya. Its aim: to know the secrets of Arabic speech and avoid error in fixing the meaning intended."},
  "ar": ["عِلْمٌ يُعْرَفُ بِهِ إِيرَادُ الْمَعْنَى الْوَاحِدِ بِطُرُقٍ مُخْتَلِفَةٍ فِي وُضُوحِ الدَّلَالَةِ عَلَيْهِ"], "notes": ["ilm-al-bayan"]},
 {"n": 5, "q": {"tr": "İlm-i beyânın vâzıı kimdir?", "en": "Who founded ʿilm al-bayān?"},
  "a": {"tr": "Medrese cevabı: Abdülkâhir el-Cürcânî'dir (ö. 471/1078); Delâilü'l-i'câz ve Esrârü'l-belâğa ile beyan ve meânînin kaidelerini tedvin etmiştir.", "en": "The madrasa's answer: ʿAbd al-Qāhir al-Jurjānī (d. 471/1078), who set down the rules of bayān and maʿānī in the Dalāʾil al-iʿjāz and the Asrār al-balāgha."},
  "ar": ["عَبْدُ الْقَاهِرِ الْجُرْجَانِيُّ"], "notes": ["ilm-al-bayan"]},
 {"n": 6, "q": {"tr": "İlm-i beyânın tarifindeki «muhtelif yollar»dan murad nedir?", "en": "What is meant by the «different ways» in the definition of ʿilm al-bayān?"},
  "a": {"tr": "Teşbih, mecaz ve kinâyedir. Kitapta önce hakikatin tarif edilmesi, mecazı ve nevilerini bilmenin hakikati bilmeye bağlı olmasındandır.", "en": "Tashbīh, majāz and kināya. The book defines the ḥaqīqa first because knowing the majāz and its kinds depends on knowing the ḥaqīqa."},
  "ar": ["التَّشْبِيهُ وَالْمَجَازُ وَالْكِنَايَةُ"], "notes": ["ilm-al-bayan"]},
 {"n": 7, "q": {"tr": "Hakikat nedir?", "en": "What is the ḥaqīqa?"},
  "a": {"tr": "Kullanıldığı mânâ mevzûun lehi olması haysiyetinden, mevzûun lehinde kullanılan lafızdır: yırtıcı hayvanda kullanılan أَسَد, el mânâsında kullanılan يَد gibi.", "en": "A word used in what it was coined for, with regard to its being what it was coined for: أَسَد for the beast of prey, يَد for the hand."},
  "ar": ["لَفْظٌ مُسْتَعْمَلٌ فِيمَا وُضِعَ لَهُ مِنْ حَيْثُ أَنَّهُ مَا وُضِعَ لَهُ"], "notes": ["haqiqa-majaz"]},
 {"n": 8, "q": {"tr": "Mecaz nedir?", "en": "What is the majāz?"},
  "a": {"tr": "Mevzûun lehi murad etmekten men eden bir karine ile beraber, mevzûun leh ile müstamelün fîh arasında bir alâka ile, kullanıldığı mânâ mevzûun lehin gayrı olması haysiyetinden mevzûun lehin gayrında kullanılan lafızdır: cesur adamda kullanılan أَسَد, nimette kullanılan يَد gibi. Mecazda dört şey vardır: mevzûun leh, müstamelün fîh, alâka, karîne-i mânia.", "en": "A word used in other than what it was coined for, with regard to that otherness, by a relation between the two senses and with a clue that bars the coined sense: أَسَد for the brave man, يَد for a favour. Four things are in a majāz: the coined sense, the sense in use, the relation and the barring clue."},
  "ar": ["لَفْظٌ مُسْتَعْمَلٌ فِي غَيْرِ مَا وُضِعَ لَهُ مِنْ حَيْثُ أَنَّهُ غَيْرُهُ بِعَلَاقَةٍ بَيْنَهُمَا مَعَ قَرِينَةٍ مَانِعَةٍ عَنْ إِرَادَةِ الْمَوْضُوعِ لَهُ", "رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ"], "notes": ["haqiqa-majaz", "qarinat-al-majaz"]},
 {"n": 9, "q": {"tr": "Kinâye nedir?", "en": "What is the kināya?"},
  "a": {"tr": "Mevzûun lehi murad etmeye mâni bir karine olmaksızın, mevzûun lehin lâzımında kullanılan lafızdır: boy uzunluğunda kullanılan طَوِيلُ النِّجَادِ gibi — kılıç bağının uzun olması murad edilebilir, fakat lâzımı olan boyun uzunluğuna kinâyedir. Cömertlikten kinâye «falanın kapısı açık» demek de böyledir.", "en": "A word used in what its coined sense entails, with no clue barring the coined sense: طَوِيلُ النِّجَادِ for tallness — a long sword-belt may be meant, yet it hints at its entailment, a tall stature. «His door is open» for generosity is the same."},
  "ar": ["لَفْظٌ مُسْتَعْمَلٌ فِي لَازِمِ مَا وُضِعَ لَهُ بِلَا قَرِينَةٍ مَانِعَةٍ عَنْهُ", "فُلَانٌ طَوِيلُ النِّجَادِ"], "notes": ["kinaya"]},
 {"n": 10, "q": {"tr": "Mecaz ile kinâye arasında ne fark vardır?", "en": "What is the difference between the majāz and the kināya?"},
  "a": {"tr": "Mecazda mevzûun lehi murad etmek karine ile men edilmiştir; kinâyede ise mevzûun lehi murad etmek câizdir, lafız lâzımında kullanılır. Kinâye, kinâye olması haysiyetinden mevzûun lehine zıt değildir; ancak Keşşâf sahibinin لَيْسَ كَمِثْلِهِ شَيْءٌ hakkındaki görüşünde olduğu gibi hususî bir maddeden dolayı mevzûun lehi murad etmek kinâyede de mümteni olabilir.", "en": "In the majāz a clue bars the coined sense; in the kināya the coined sense remains permissible while the word is used for its entailment. The kināya as such is not contrary to its coined sense — though, as the author of the Kashshāf holds of لَيْسَ كَمِثْلِهِ شَيْءٌ, the coined sense may be impossible for a particular reason."},
  "ar": ["لَيْسَ كَمِثْلِهِ شَيْءٌ"], "notes": ["farq-al-kinaya-wal-majaz", "kinaya"]},
 {"n": 11, "q": {"tr": "Hakikat ve mecazın tarifindeki «haysiyet» kaydı niçindir?", "en": "Why the restriction «with regard to» in the definitions of ḥaqīqa and majāz?"},
  "a": {"tr": "Her birinin tarifi diğeriyle bozulmasın diye: صَلَاة lafzı lügatte duâ, şer'an namazdır; duâ mânâsında kullanıldığı yerde lügaten hakikat, şer'an mecaz; namaz mânâsında kullanıldığı yerde şer'an hakikat, lügaten mecazdır.", "en": "So that neither definition is broken by the other: صَلَاة means prayer-of-supplication in the language and the ritual prayer in the law; used for supplication it is ḥaqīqa in the language and majāz in the law, and for the ritual prayer the reverse."},
  "ar": ["الصَّلَاةُ"], "notes": ["haqiqa-majaz"]},
 {"n": 12, "q": {"tr": "Mecazın tarifindeki «alâka» kaydı niçindir?", "en": "Why the restriction «by a relation» in the definition of majāz?"},
  "a": {"tr": "Kitaba işaret ederek «خُذْ هَذَا الْفَرَسَ» demek gibi galatı tariften çıkarmak içindir.", "en": "To keep out the slip of the tongue — saying «خُذْ هَذَا الْفَرَسَ» while pointing at a book."},
  "ar": ["خُذْ هَذَا الْفَرَسَ"], "notes": ["qarinat-al-majaz", "haqiqa-majaz"]},
 {"n": 13, "q": {"tr": "Mecazın tarifindeki «karine» kaydı niçindir?", "en": "Why the restriction «with a barring clue» in the definition of majāz?"},
  "a": {"tr": "Mevzûun lehi murad etmek câiz olmakla beraber gayrında kullanılan kinâyeyi mecazdan çıkarmak içindir.", "en": "To keep out the kināya, which is used for something other than its coined sense while the coined sense stays permissible."},
  "ar": ["الْقَرِينَةُ الْمَانِعَةُ"], "notes": ["qarinat-al-majaz"]},
 {"n": 14, "q": {"tr": "Alâka nasıl itibar olunur?", "en": "How is the relation reckoned?"},
  "a": {"tr": "Küllî ve cüz'î olmak üzere iki şekilde. Küllî alâka: müstamelün fîhin mevzûun lehe lâzım olmasıdır — buradaki lüzum, iki mânâ arasında birinden diğerine intikal olunan ittisaldir. Cüz'î alâka: müstamelün fîhin mevzûun lehe müşâbih veya gayr-i müşâbih olmasıdır; alâkası müşâbehet olan mecaza mecâz-ı istiâre, gayr-i müşâbehet olana mecâz-ı mürsel denir.", "en": "In two ways, general and particular. The general relation: the sense in use is entailed by the coined sense — entailment here being the connection by which the mind passes from one to the other. The particular: the sense in use resembles the coined sense or does not; a majāz whose relation is likeness is the istiʿāra, one whose relation is anything else the majāz mursal."},
  "ar": ["الْعَلَاقَةُ الْكُلِّيَّةُ وَالْجُزْئِيَّةُ"], "notes": ["majaz-mursal", "istiara"]},
 {"n": 15, "q": {"tr": "Mecâz-ı istiâre nedir?", "en": "What is the majāz of istiʿāra?"},
  "a": {"tr": "Alâkası müşâbehet olan mecazdır: رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ'de أَسَد — hakikî mânâsı yırtıcı hayvan, mecâzî mânâsı cesur adam, alâka müşâbehet, karîne-i mânia فِي يَدِهِ سَيْفٌ.", "en": "The majāz whose relation is likeness: أَسَد in رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ — literal sense the beast, figurative sense the brave man, relation likeness, barring clue فِي يَدِهِ سَيْفٌ."},
  "ar": ["رَأَيْتُ أَسَدًا فِي يَدِهِ سَيْفٌ"], "notes": ["istiara", "arkan-al-istiara"]},
 {"n": 16, "q": {"tr": "Mecâz-ı mürsel nedir?", "en": "What is the majāz mursal?"},
  "a": {"tr": "Alâkası müşâbehetin gayrı olan mecazdır: nimet mânâsında يَد, kuyu kovası mânâsında رَاوِيَة gibi.", "en": "The majāz whose relation is other than likeness: يَد for a favour, رَاوِيَة for the water-skin."},
  "ar": ["فَالْمُرْسَلُ كَالْيَدِ فِي النِّعْمَةِ وَالْقُدْرَةِ وَالرَّاوِيَةِ فِي الْمَزَادَةِ"], "notes": ["majaz-mursal"]},
 {"n": 17, "q": {"tr": "Mecâz-ı mürseller kaçtır?", "en": "How many kinds of majāz mursal are there?"},
  "a": {"tr": "Yirmi yedidir: masdariyyet, mazhariyyet, mücâveret, cüz'iyyet, külliyyet, sebebiyyet, müsebbebiyyet, kevn-i sâbık, kevn-i lâhık, mahalliyyet, hâlliyyet, âliyyet, ıtlak, takyid, umum, husus, kuvvet, lâzımiyyet, melzûmiyyet, illiyyet, ma'lûliyyet, müteallikiyyet, müteallakiyyet, şartiyyet, meşrûtiyyet, dâlliyyet, medlûliyyet.", "en": "Twenty-seven: maṣdariyya, maẓhariyya, mujāwara, juzʾiyya, kulliyya, sababiyya, musabbabiyya, kawn sābiq, kawn lāḥiq, maḥalliyya, ḥālliyya, āliyya, iṭlāq, taqyīd, ʿumūm, khuṣūṣ, quwwa, lāzimiyya, malzūmiyya, ʿilliyya, maʿlūliyya, mutaʿalliqiyya, mutaʿallaqiyya, sharṭiyya, mashrūṭiyya, dālliyya, madlūliyya."},
  "ar": ["الْمَجَازَاتُ الْمُرْسَلَةُ سَبْعَةٌ وَعِشْرُونَ"], "notes": ["majaz-mursal"]},
 {"n": 18, "q": {"tr": "Masdariyyet alâkası nedir?", "en": "What is the relation of maṣdariyya?"},
  "a": {"tr": "Hakikî mânânın, mecâzî mânâ için sudûr mahalli (çıkış yeri) olmasıdır: أَعْجَبَنِي يَدُ فُلَانٍ — يَد mecazdır; hakikî mânâsı el, mecâzî mânâsı nimet; el, nimetin çıkış yeridir. Karine: أَعْجَبَنِي'nin ele isnadı — el taaccüb vermez. İfade: ذِكْرُ الْيَدِ إِرَادَةُ النِّعْمَةِ.", "en": "The literal sense is the source from which the figurative issues: أَعْجَبَنِي يَدُ فُلَانٍ — يَد is a majāz; literal the hand, figurative the favour; the hand is where favours issue. Clue: wonder is predicated of a hand. Formula: ذِكْرُ الْيَدِ إِرَادَةُ النِّعْمَةِ."},
  "ar": ["أَعْجَبَنِي يَدُ فُلَانٍ", "ذِكْرُ الْيَدِ إِرَادَةُ النِّعْمَةِ"], "notes": ["majaz-mursal"]},
 {"n": 19, "q": {"tr": "Mazhariyyet alâkası nedir?", "en": "What is the relation of maẓhariyya?"},
  "a": {"tr": "Hakikî mânânın, mecâzî mânâ için zuhur mahalli olmasıdır: يَدُ اللهِ فَوْقَ أَيْدِيهِمْ — يَد mecazdır; hakikî mânâsı el, mecâzî mânâsı kudret; el, kudretin göründüğü yerdir. Karine: elin Allah'a izâfeti. İfade: ذِكْرُ الْيَدِ إِرَادَةُ الْقُدْرَةِ.", "en": "The literal sense is the place where the figurative appears: يَدُ اللهِ فَوْقَ أَيْدِيهِمْ — يَد is a majāz; literal the hand, figurative power; the hand is where power shows. Clue: the hand annexed to God. Formula: ذِكْرُ الْيَدِ إِرَادَةُ الْقُدْرَةِ."},
  "ar": ["يَدُ اللهِ فَوْقَ أَيْدِيهِمْ", "ذِكْرُ الْيَدِ إِرَادَةُ الْقُدْرَةِ"], "notes": ["majaz-mursal"]},
 {"n": 20, "q": {"tr": "Masdariyyet ile mazhariyyet arasında ne fark vardır?", "en": "What is the difference between maṣdariyya and maẓhariyya?"},
  "a": {"tr": "Masdariyyette mecâzî mânâ, mahalli olan hakikî mânâdan ayrılır — ihsan elden ayrıldığı gibi. Mazhariyyette mecâzî mânâ, mahalli olan hakikî mânâdan ayrılmaz — kudret elden ayrılmadığı gibi.", "en": "In maṣdariyya the figurative parts from its literal seat, as a favour leaves the hand; in maẓhariyya it does not, as power never leaves the hand."},
  "ar": ["الْمَصْدَرِيَّةُ وَالْمَظْهَرِيَّةُ"], "notes": ["majaz-mursal"]},
 {"n": 21, "q": {"tr": "Mücâveret alâkası nedir?", "en": "What is the relation of mujāwara?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâya yakın (komşu) olmasıdır: شَرِبْتُ مِنَ الرَّاوِيَةِ — رَاوِيَة mecazdır; hakikî mânâsı su taşıyan hayvan, mecâzî mânâsı kırba. Karine: شَرِبْتُ'nün râviyeye taallûku — hayvandan su içilmez. İfade: ذِكْرُ الرَّاوِيَةِ إِرَادَةُ الدَّلْوِ.", "en": "The literal sense neighbours the figurative: شَرِبْتُ مِنَ الرَّاوِيَةِ — رَاوِيَة is a majāz; literal the water-carrying beast, figurative the skin it carries. Clue: one does not drink from a beast. Formula: ذِكْرُ الرَّاوِيَةِ إِرَادَةُ الدَّلْوِ."},
  "ar": ["شَرِبْتُ مِنَ الرَّاوِيَةِ"], "notes": ["majaz-mursal"]},
 {"n": 22, "q": {"tr": "Cüz'iyyet alâkası nedir?", "en": "What is the relation of juzʾiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için cüz olmasıdır: اطَّلَعَتِ الْعَيْنُ عَلَيْنَا — عَيْن mecazdır; hakikî mânâsı göz, mecâzî mânâsı câsus; göz, câsusun bir cüz'üdür. Karine: اطَّلَعَتْ'in göze isnadı — göz değil insan muttali olur. İfade: ذِكْرُ الْجُزْءِ إِرَادَةُ الْكُلِّ.", "en": "The literal sense is a part of the figurative: اطَّلَعَتِ الْعَيْنُ عَلَيْنَا — عَيْن is a majāz; literal the eye, figurative the scout; the eye is a part of him. Clue: it is a man, not an eye, who finds out. Formula: ذِكْرُ الْجُزْءِ إِرَادَةُ الْكُلِّ."},
  "ar": ["اطَّلَعَتِ الْعَيْنُ عَلَيْنَا", "كَالْعَيْنِ فِي الرَّبِيئَةِ"], "notes": ["majaz-mursal"]},
 {"n": 23, "q": {"tr": "Külliyyet alâkası nedir?", "en": "What is the relation of kulliyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için kül olmasıdır: يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ — أَصَابِع mecazdır; hakikî mânâsı parmaklar, mecâzî mânâsı parmak uçları (أَنَامِل). Karine: فِي آذَانِهِمْ — kulağa parmaklar değil uçları tıkanır. İfade: ذِكْرُ الْكُلِّ إِرَادَةُ الْجُزْءِ.", "en": "The literal sense is the whole of the figurative: يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ — أَصَابِع is a majāz; literal the fingers, figurative the fingertips. Clue: it is the tips, not the fingers, that go into the ears. Formula: ذِكْرُ الْكُلِّ إِرَادَةُ الْجُزْءِ."},
  "ar": ["يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِمْ", "كَالْأَصَابِعِ فِي الْأَنَامِلِ"], "notes": ["majaz-mursal"]},
 {"n": 24, "q": {"tr": "Sebebiyyet alâkası nedir?", "en": "What is the relation of sababiyya?"},
  "a": {"tr": "Hakikî mânânın mecâzî mânâ için sebep olmasıdır: رَعَيْنَا الْغَيْثَ — غَيْث mecazdır; hakikî mânâsı yağmur, mecâzî mânâsı ot; yağmur otun sebebidir. Karine: رَعَيْنَا'nın gayse taallûku — yağmur otlatılmaz. İfade: ذِكْرُ السَّبَبِ إِرَادَةُ الْمُسَبَّبِ.", "en": "The literal sense is the cause of the figurative: رَعَيْنَا الْغَيْثَ — غَيْث is a majāz; literal the rain, figurative the herbage; rain causes herbage. Clue: rain is not grazed. Formula: ذِكْرُ السَّبَبِ إِرَادَةُ الْمُسَبَّبِ."},
  "ar": ["رَعَيْنَا الْغَيْثَ", "ذِكْرُ السَّبَبِ إِرَادَةُ الْمُسَبَّبِ"], "notes": ["majaz-mursal"]},
]
